insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000001951', 'get the ball rolling', '/ɡet ðə bɔːl ˈroʊlɪŋ/', 'phrase', 'começar algo', 'Let''s get the ball rolling on this project.', 'Vamos começar este projeto.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001952', 'hit the nail on the head', '/hɪt ðə neɪl ɒn ðə hed/', 'phrase', 'acertar em cheio', 'You really hit the nail on the head with that comment.', 'Você realmente acertou em cheio com esse comentário.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001953', 'once in a blue moon', '/wʌns ɪn ə bluː muːn/', 'phrase', 'muito raramente', 'We only eat out once in a blue moon.', 'Só comemos fora muito raramente.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001954', 'cut corners', '/kʌt ˈkɔːrnərz/', 'phrase', 'economizar na qualidade', 'The company cut corners on safety to save money.', 'A empresa fez corpo mole na segurança para economizar dinheiro.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001955', 'call it a day', '/kɔːl ɪt ə deɪ/', 'phrase', 'encerrar por hoje', 'We''ve worked hard enough, let''s call it a day.', 'Trabalhamos bastante, vamos encerrar por hoje.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001956', 'under the weather', '/ˈʌndər ðə ˈweðər/', 'phrase', 'meio doente', 'She stayed home because she was feeling under the weather.', 'Ela ficou em casa porque estava meio doente.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001957', 'break the ice', '/breɪk ðə aɪs/', 'phrase', 'quebrar o gelo', 'He told a joke to break the ice at the meeting.', 'Ele contou uma piada para quebrar o gelo na reunião.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001958', 'see eye to eye', '/siː aɪ tuː aɪ/', 'phrase', 'concordar', 'They finally saw eye to eye on the budget.', 'Eles finalmente concordaram sobre o orçamento.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001959', 'on the same page', '/ɒn ðə seɪm peɪdʒ/', 'phrase', 'alinhados', 'Before we start, let''s make sure we are on the same page.', 'Antes de começarmos, vamos garantir que estamos alinhados.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001960', 'get out of hand', '/ɡet aʊt əv hænd/', 'phrase', 'sair do controle', 'The party got out of hand and the neighbors complained.', 'A festa saiu do controle e os vizinhos reclamaram.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001961', 'spill the beans', '/spɪl ðə biːnz/', 'phrase', 'contar um segredo', 'She accidentally spilled the beans about the surprise party.', 'Ela sem querer contou o segredo da festa surpresa.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001962', 'bite the bullet', '/baɪt ðə ˈbʊlɪt/', 'phrase', 'engolir o sapo', 'He finally bit the bullet and asked for a raise.', 'Ele finalmente engoliu o sapo e pediu um aumento.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001963', 'weigh the pros and cons', '/weɪ ðə proʊz ænd kɑːnz/', 'phrase', 'pesar prós e contras', 'We need to weigh the pros and cons before deciding.', 'Precisamos pesar os prós e contras antes de decidir.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001964', 'make a decision', '/meɪk ə dɪˈsɪʒən/', 'phrase', 'tomar uma decisão', 'It is time to make a decision about the new office.', 'É hora de tomar uma decisão sobre o novo escritório.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001965', 'take a risk', '/teɪk ə rɪsk/', 'phrase', 'correr um risco', 'Sometimes you have to take a risk to grow your business.', 'Às vezes você precisa correr um risco para expandir seu negócio.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001966', 'keep in touch', '/kiːp ɪn tʌtʃ/', 'phrase', 'manter contato', 'Let''s keep in touch after the conference.', 'Vamos manter contato depois da conferência.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001967', 'pay attention', '/peɪ əˈtenʃən/', 'phrase', 'prestar atenção', 'Please pay attention during the presentation.', 'Por favor, preste atenção durante a apresentação.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001968', 'do research', '/duː rɪˈsɜːrtʃ/', 'phrase', 'fazer pesquisa', 'She did research before buying a new car.', 'Ela fez pesquisa antes de comprar um carro novo.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001969', 'reach an agreement', '/riːtʃ ən əˈɡriːmənt/', 'phrase', 'chegar a um acordo', 'The two companies finally reached an agreement.', 'As duas empresas finalmente chegaram a um acordo.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001970', 'face the consequences', '/feɪs ðə ˈkɑːnsəkwensɪz/', 'phrase', 'encarar as consequências', 'He had to face the consequences of his actions.', 'Ele teve que encarar as consequências de suas ações.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001971', 'take advantage of', '/teɪk ədˈvæntɪdʒ əv/', 'phrase', 'aproveitar', 'You should take advantage of this opportunity.', 'Você deveria aproveitar essa oportunidade.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001972', 'raise awareness', '/reɪz əˈwernəs/', 'phrase', 'aumentar a conscientização', 'The campaign aims to raise awareness about recycling.', 'A campanha visa aumentar a conscientização sobre reciclagem.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001973', 'let the cat out of the bag', '/let ðə kæt aʊt əv ðə bæɡ/', 'phrase', 'deixar escapar um segredo', 'He let the cat out of the bag about the promotion.', 'Ele deixou escapar o segredo sobre a promoção.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001974', 'a piece of cake', '/ə piːs əv keɪk/', 'phrase', 'muito fácil', 'The test was a piece of cake for her.', 'A prova foi muito fácil para ela.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001975', 'cost an arm and a leg', '/kɔːst ən ɑːrm ænd ə leɡ/', 'phrase', 'custar muito caro', 'That new laptop cost an arm and a leg.', 'Aquele notebook novo custou os olhos da cara.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001976', 'burn the midnight oil', '/bɜːrn ðə ˈmɪdnaɪt ɔɪl/', 'phrase', 'trabalhar até tarde', 'She burned the midnight oil to finish the report.', 'Ela trabalhou até tarde da noite para terminar o relatório.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001977', 'jump on the bandwagon', '/dʒʌmp ɒn ðə ˈbændwæɡən/', 'phrase', 'entrar na onda', 'Many brands jumped on the bandwagon after the trend went viral.', 'Muitas marcas entraram na onda depois que a tendência viralizou.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001978', 'back to square one', '/bæk tuː skwer wʌn/', 'phrase', 'voltar à estaca zero', 'The deal fell through, so we''re back to square one.', 'O acordo não foi adiante, então voltamos à estaca zero.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001979', 'the best of both worlds', '/ðə best əv boʊθ wɜːrldz/', 'phrase', 'o melhor dos dois mundos', 'Working remotely gives her the best of both worlds.', 'Trabalhar remotamente dá a ela o melhor dos dois mundos.', 'B2', array['idioms']),
('30000000-0000-0000-0000-000000001980', 'think outside the box', '/θɪŋk aʊtˈsaɪd ðə bɑːks/', 'phrase', 'pensar fora da caixa', 'The team was encouraged to think outside the box.', 'A equipe foi incentivada a pensar fora da caixa.', 'B2', array['idioms']);

