-- Lição 326: Idioms do dia a dia (get the ball rolling, hit the nail on the head, once in a blue moon, cut corners, call it a day, under the weather)
insert into exercises (lesson_id, type, sort_order, content) values
('20000000-0000-0000-0000-000000000326', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001951", "show_image": false}'),
('20000000-0000-0000-0000-000000000326', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001952", "show_image": false}'),
('20000000-0000-0000-0000-000000000326', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001956", "show_image": false}'),
('20000000-0000-0000-0000-000000000326', 'multiple_choice', 4, '{"question": "Let''s ___ on this project.", "audio_text": null, "options": ["get the ball rolling", "call it a day", "cut corners"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000326', 'multiple_choice', 5, '{"question": "She stayed home because she was feeling ___.", "audio_text": null, "options": ["under the weather", "once in a blue moon", "on the same page"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000326', 'matching', 6, '{"pairs": [{"left": "get the ball rolling", "right": "começar algo"}, {"left": "hit the nail on the head", "right": "acertar em cheio"}, {"left": "once in a blue moon", "right": "muito raramente"}, {"left": "cut corners", "right": "economizar na qualidade"}, {"left": "call it a day", "right": "encerrar por hoje"}, {"left": "under the weather", "right": "meio doente"}]}'),
('20000000-0000-0000-0000-000000000326', 'fill_blank', 7, '{"sentence": "You really ___ with that comment.", "options": ["hit the nail on the head", "cut corners", "called it a day"], "correct": "hit the nail on the head", "translation": "Você realmente acertou em cheio com esse comentário."}'),
('20000000-0000-0000-0000-000000000326', 'fill_blank', 8, '{"sentence": "The company ___ on safety to save money.", "options": ["cut corners", "got the ball rolling", "broke the ice"], "correct": "cut corners", "translation": "A empresa fez corpo mole na segurança para economizar dinheiro."}'),
('20000000-0000-0000-0000-000000000326', 'word_order', 9, '{"words": ["We", "only", "eat", "out", "once", "in", "a", "blue", "moon"], "correct_sentence": "We only eat out once in a blue moon", "translation": "Só comemos fora muito raramente"}'),
('20000000-0000-0000-0000-000000000326', 'word_order', 10, '{"words": ["We''ve", "worked", "hard", "enough", "let''s", "call", "it", "a", "day"], "correct_sentence": "We''ve worked hard enough let''s call it a day", "translation": "Trabalhamos bastante, vamos encerrar por hoje"}'),
('20000000-0000-0000-0000-000000000326', 'reading', 11, '{"passage": "Everyday idioms make conversations sound more natural. To start a new project, you might say ''let''s get the ball rolling''. When someone makes a very accurate comment, they ''hit the nail on the head''. And when it is time to finish work, people often say ''let''s call it a day''.", "translation": "Idioms do dia a dia deixam as conversas mais naturais. Para começar um novo projeto, você pode dizer ''let''s get the ball rolling''. Quando alguém faz um comentário muito preciso, essa pessoa ''hit the nail on the head''. E quando é hora de terminar o trabalho, as pessoas costumam dizer ''let''s call it a day''.", "question": "What do people say when it is time to finish work, according to the text?", "options": ["Let''s get the ball rolling", "Let''s call it a day", "Let''s cut corners"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000326', 'listening', 12, '{"audio_text": "Let''s get the ball rolling on this project. You really hit the nail on the head with that comment. She stayed home because she was feeling under the weather.", "question": "Why did she stay home, according to the audio?", "options": ["She was busy", "She was feeling under the weather", "She was on vacation"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000326', 'dictation', 13, '{"audio_text": "Let''s get the ball rolling on this project.", "expected": "Let''s get the ball rolling on this project."}'),
('20000000-0000-0000-0000-000000000326', 'typing', 14, '{"prompt_pt": "Traduza usando uma expressão idiomática: ''Já trabalhamos o suficiente hoje, vamos encerrar por hoje.''", "expected": "We''ve worked enough today, let''s call it a day.", "ai_review": true}'),

-- Lição 327: Idioms de relacionamento e trabalho (break the ice, see eye to eye, on the same page, get out of hand, spill the beans, bite the bullet)
('20000000-0000-0000-0000-000000000327', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001957", "show_image": false}'),
('20000000-0000-0000-0000-000000000327', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001959", "show_image": false}'),
('20000000-0000-0000-0000-000000000327', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001962", "show_image": false}'),
('20000000-0000-0000-0000-000000000327', 'multiple_choice', 4, '{"question": "He told a joke to ___ at the meeting.", "audio_text": null, "options": ["break the ice", "spill the beans", "get out of hand"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000327', 'multiple_choice', 5, '{"question": "They finally ___ on the budget.", "audio_text": null, "options": ["saw eye to eye", "bit the bullet", "spilled the beans"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000327', 'matching', 6, '{"pairs": [{"left": "break the ice", "right": "quebrar o gelo"}, {"left": "see eye to eye", "right": "concordar"}, {"left": "on the same page", "right": "alinhados"}, {"left": "get out of hand", "right": "sair do controle"}, {"left": "spill the beans", "right": "contar um segredo"}, {"left": "bite the bullet", "right": "engolir o sapo"}]}'),
('20000000-0000-0000-0000-000000000327', 'fill_blank', 7, '{"sentence": "Before we start, let''s make sure we are ___.", "options": ["on the same page", "under the weather", "getting out of hand"], "correct": "on the same page", "translation": "Antes de começarmos, vamos garantir que estamos alinhados."}'),
('20000000-0000-0000-0000-000000000327', 'fill_blank', 8, '{"sentence": "She accidentally ___ about the surprise party.", "options": ["spilled the beans", "broke the ice", "bit the bullet"], "correct": "spilled the beans", "translation": "Ela sem querer contou o segredo da festa surpresa."}'),
('20000000-0000-0000-0000-000000000327', 'word_order', 9, '{"words": ["The", "party", "got", "out", "of", "hand", "and", "the", "neighbors", "complained"], "correct_sentence": "The party got out of hand and the neighbors complained", "translation": "A festa saiu do controle e os vizinhos reclamaram"}'),
('20000000-0000-0000-0000-000000000327', 'word_order', 10, '{"words": ["He", "finally", "bit", "the", "bullet", "and", "asked", "for", "a", "raise"], "correct_sentence": "He finally bit the bullet and asked for a raise", "translation": "Ele finalmente engoliu o sapo e pediu um aumento"}'),
('20000000-0000-0000-0000-000000000327', 'reading', 11, '{"passage": "Idioms are common when describing relationships and teamwork. A joke can break the ice at a first meeting, and two people who agree see eye to eye. Teams that share the same goals are on the same page, but sometimes a situation can get out of hand, and someone has to bite the bullet and take action.", "translation": "Idioms são comuns ao descrever relacionamentos e trabalho em equipe. Uma piada pode break the ice em uma primeira reunião, e duas pessoas que concordam see eye to eye. Equipes que compartilham os mesmos objetivos estão on the same page, mas às vezes uma situação pode get out of hand, e alguém precisa bite the bullet e agir.", "question": "What can a joke do at a first meeting, according to the text?", "options": ["Get out of hand", "Break the ice", "Spill the beans"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000327', 'listening', 12, '{"audio_text": "He told a joke to break the ice at the meeting. They finally saw eye to eye on the budget. The party got out of hand and the neighbors complained.", "question": "What did they finally agree on, according to the audio?", "options": ["The schedule", "The budget", "The location"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000327', 'dictation', 13, '{"audio_text": "They finally saw eye to eye on the budget.", "expected": "They finally saw eye to eye on the budget."}'),
('20000000-0000-0000-0000-000000000327', 'typing', 14, '{"prompt_pt": "Traduza usando uma expressão idiomática: ''Precisamos garantir que estamos alinhados antes de começar.''", "expected": "We need to make sure we are on the same page before we start.", "ai_review": true}'),

-- Lição 328: Collocations com verbos comuns (weigh the pros and cons, make a decision, take a risk, keep in touch, pay attention, do research)
('20000000-0000-0000-0000-000000000328', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001964", "show_image": false}'),
('20000000-0000-0000-0000-000000000328', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001967", "show_image": false}'),
('20000000-0000-0000-0000-000000000328', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001968", "show_image": false}'),
('20000000-0000-0000-0000-000000000328', 'multiple_choice', 4, '{"question": "It is time to ___ about the new office.", "audio_text": null, "options": ["make a decision", "do a decision", "take a decision"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000328', 'multiple_choice', 5, '{"question": "Sometimes you have to ___ to grow your business.", "audio_text": null, "options": ["take a risk", "make a risk", "do a risk"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000328', 'matching', 6, '{"pairs": [{"left": "weigh the pros and cons", "right": "pesar prós e contras"}, {"left": "make a decision", "right": "tomar uma decisão"}, {"left": "take a risk", "right": "correr um risco"}, {"left": "keep in touch", "right": "manter contato"}, {"left": "pay attention", "right": "prestar atenção"}, {"left": "do research", "right": "fazer pesquisa"}]}'),
('20000000-0000-0000-0000-000000000328', 'fill_blank', 7, '{"sentence": "Please ___ during the presentation.", "options": ["pay attention", "make attention", "do attention"], "correct": "pay attention", "translation": "Por favor, preste atenção durante a apresentação."}'),
('20000000-0000-0000-0000-000000000328', 'fill_blank', 8, '{"sentence": "She ___ before buying a new car.", "options": ["did research", "made research", "took research"], "correct": "did research", "translation": "Ela fez pesquisa antes de comprar um carro novo."}'),
('20000000-0000-0000-0000-000000000328', 'word_order', 9, '{"words": ["We", "need", "to", "weigh", "the", "pros", "and", "cons", "before", "deciding"], "correct_sentence": "We need to weigh the pros and cons before deciding", "translation": "Precisamos pesar os prós e contras antes de decidir"}'),
('20000000-0000-0000-0000-000000000328', 'word_order', 10, '{"words": ["Let''s", "keep", "in", "touch", "after", "the", "conference"], "correct_sentence": "Let''s keep in touch after the conference", "translation": "Vamos manter contato depois da conferência"}'),
('20000000-0000-0000-0000-000000000328', 'reading', 11, '{"passage": "Certain verbs and nouns always go together in English — these are called collocations. You make a decision (not ''do'' one), take a risk (not ''make'' one), pay attention, and do research. Getting these combinations right, along with weighing the pros and cons of a situation, makes your English sound much more natural.", "translation": "Certos verbos e substantivos sempre andam juntos em inglês — essas são as chamadas collocations. Você make a decision (não ''do''), take a risk (não ''make''), pay attention, e do research. Acertar essas combinações, junto com weighing the pros and cons de uma situação, faz seu inglês soar muito mais natural.", "question": "What verb goes with ''research'', according to the text?", "options": ["Make", "Take", "Do"], "correct_index": 2}'),
('20000000-0000-0000-0000-000000000328', 'listening', 12, '{"audio_text": "It is time to make a decision about the new office. Sometimes you have to take a risk to grow your business. Please pay attention during the presentation.", "question": "What is it time to do, according to the audio?", "options": ["Take a risk", "Make a decision", "Do research"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000328', 'dictation', 13, '{"audio_text": "It is time to make a decision about the new office.", "expected": "It is time to make a decision about the new office."}'),
('20000000-0000-0000-0000-000000000328', 'typing', 14, '{"prompt_pt": "Traduza (use as collocations corretas): ''Ela fez pesquisa, pesou os prós e contras e tomou uma decisão.''", "expected": "She did research, weighed the pros and cons, and made a decision.", "ai_review": true}'),

