('20000000-0000-0000-0000-000000000329', 'word_order', 9, '{"words": ["You", "should", "take", "advantage", "of", "this", "opportunity"], "correct_sentence": "You should take advantage of this opportunity", "translation": "Você deveria aproveitar essa oportunidade"}'),
('20000000-0000-0000-0000-000000000329', 'word_order', 10, '{"words": ["He", "let", "the", "cat", "out", "of", "the", "bag", "about", "the", "promotion"], "correct_sentence": "He let the cat out of the bag about the promotion", "translation": "Ele deixou escapar o segredo sobre a promoção"}'),
('20000000-0000-0000-0000-000000000329', 'reading', 11, '{"passage": "More formal collocations are common in negotiations and news reports. Two sides reach an agreement after long talks, and someone who breaks the rules must face the consequences. Companies often take advantage of opportunities and run campaigns to raise awareness about important issues, though sometimes someone lets the cat out of the bag before an official announcement.", "translation": "Collocations mais formais são comuns em negociações e reportagens. Dois lados reach an agreement depois de longas conversas, e quem quebra as regras precisa face the consequences. Empresas costumam take advantage of oportunidades e fazem campanhas para raise awareness sobre questões importantes, embora às vezes alguém let the cat out of the bag antes de um anúncio oficial.", "question": "What might someone do before an official announcement, according to the text?", "options": ["Reach an agreement", "Let the cat out of the bag", "Face the consequences"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000329', 'listening', 12, '{"audio_text": "The two companies finally reached an agreement. He had to face the consequences of his actions. You should take advantage of this opportunity.", "question": "What did the two companies finally do, according to the audio?", "options": ["Reach an agreement", "Face the consequences", "Raise awareness"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000329', 'dictation', 13, '{"audio_text": "The two companies finally reached an agreement.", "expected": "The two companies finally reached an agreement."}'),
('20000000-0000-0000-0000-000000000329', 'typing', 14, '{"prompt_pt": "Traduza usando collocations: ''A campanha ajudou a aumentar a conscientização, e as duas empresas chegaram a um acordo.''", "expected": "The campaign helped raise awareness, and the two companies reached an agreement.", "ai_review": true}'),

