('20000000-0000-0000-0000-000000000330', 'fill_blank', 8, '{"sentence": "The deal fell through, so we''re ___.", "options": ["back to square one", "on the same page", "a piece of cake"], "correct": "back to square one", "translation": "O acordo não foi adiante, então voltamos à estaca zero."}'),
('20000000-0000-0000-0000-000000000330', 'word_order', 9, '{"words": ["Many", "brands", "jumped", "on", "the", "bandwagon", "after", "the", "trend", "went", "viral"], "correct_sentence": "Many brands jumped on the bandwagon after the trend went viral", "translation": "Muitas marcas entraram na onda depois que a tendência viralizou"}'),
('20000000-0000-0000-0000-000000000330', 'word_order', 10, '{"words": ["Working", "remotely", "gives", "her", "the", "best", "of", "both", "worlds"], "correct_sentence": "Working remotely gives her the best of both worlds", "translation": "Trabalhar remotamente dá a ela o melhor dos dois mundos"}'),
('20000000-0000-0000-0000-000000000330', 'reading', 11, '{"passage": "A good story often uses several idioms together. The new equipment cost an arm and a leg, so the team burned the midnight oil trying to make it work. When competitors began to jump on the bandwagon, the project seemed to go back to square one. In the end, thinking outside the box gave the company the best of both worlds: lower costs and better results.", "translation": "Uma boa história costuma usar várias idioms juntas. O novo equipamento cost an arm and a leg, então a equipe burned the midnight oil tentando fazê-lo funcionar. Quando concorrentes começaram a jump on the bandwagon, o projeto pareceu voltar back to square one. No final, pensar outside the box deu à empresa the best of both worlds: custos menores e melhores resultados.", "question": "What gave the company the best of both worlds, according to the text?", "options": ["Burning the midnight oil", "Thinking outside the box", "Jumping on the bandwagon"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000330', 'listening', 12, '{"audio_text": "That new laptop cost an arm and a leg. She burned the midnight oil to finish the report. The team was encouraged to think outside the box.", "question": "What did she burn the midnight oil for, according to the audio?", "options": ["To finish the report", "To buy a laptop", "To join the team"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000330', 'dictation', 13, '{"audio_text": "The team was encouraged to think outside the box.", "expected": "The team was encouraged to think outside the box."}'),
('20000000-0000-0000-0000-000000000330', 'typing', 14, '{"prompt_pt": "Traduza usando uma expressão idiomática: ''O projeto voltou à estaca zero, então precisamos pensar fora da caixa.''", "expected": "The project is back to square one, so we need to think outside the box.", "ai_review": true}'),
('20000000-0000-0000-0000-000000000330', 'typing', 15, '{"prompt_pt": "Traduza usando uma expressão idiomática: ''O carro novo custou os olhos da cara, mas nos deu o melhor dos dois mundos.''", "expected": "The new car cost an arm and a leg, but it gave us the best of both worlds.", "ai_review": true}');

